mapper.select:
select a.id, a.category_id, c.name as category_name, a.code, a.name, a.spec, a.unit, a.price, a.image, a.status, a.description, a.create_time, a.update_time from asset a left join asset_category c on a.category_id = c.id
and a.name like concat('%', #{name}, '%')
and a.code like concat('%', #{code}, '%')
and a.category_id = #{categoryId}
and a.status = #{status}
order by a.create_time desc

mapper.update:
update asset
category_id = #{categoryId}, code = #{code}, name = #{name}, spec = #{spec}, unit = #{unit}, price = #{price}, image = #{image}, status = #{status}, description = #{description}, update_time = #{updateTime}, update_user = #{updateUser}
where id = #{id}
